<?php

declare(strict_types=1);

namespace App\Play\Domain\Campaign\Lists;

/**
 * The campaign already holds a Thread with this id. Ids are generated by the caller, so a repeated
 * command must not replace the existing Thread.
 */
final class ThreadAlreadyExists extends \DomainException
{
    public static function withId(ThreadId $id): self
    {
        return new self(\sprintf('Thread "%s" already exists.', $id->toString()));
    }
}
